package br.com.onda;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.Build;
import android.provider.*;
import androidx.media3.common.MediaItem;
import java.io.*;
import java.util.*;
import org.json.*;

@androidx.media3.common.util.UnstableApi
final class FavoriteCopies {
 static final long MAX=512L*1024*1024;static final int MAX_ITEMS=1000,MAX_JSON=4*1024*1024;
 interface Control {void check()throws IOException;void bytes(long stored,long expected)throws IOException;}
 static String extension(String name,String mime){int dot=name==null?-1:name.lastIndexOf('.');String ext=dot>=0?name.substring(dot+1).toLowerCase(Locale.ROOT):"";if(ext.matches("[a-z0-9]{1,8}"))return ext;switch(mime==null?"":mime){case "audio/mpeg":return "mp3";case "audio/mp4":return "m4a";case "audio/flac":return "flac";case "audio/wav":case "audio/x-wav":return "wav";case "audio/ogg":return "ogg";case "audio/opus":return "opus";case "audio/aac":return "aac";default:return "audio";}}
 static String prepare(Context c,List<MediaItem> items)throws Exception{if(items.isEmpty()||items.size()>MAX_ITEMS)throw new IOException("Selecione de 1 a 1.000 favoritas por operação.");JSONArray queue=new JSONArray();Set<String> seen=new HashSet<>();for(MediaItem item:items){if(item.localConfiguration==null)continue;Uri uri=item.localConfiguration.uri;if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme()))continue;Uri key=uri;if(Build.VERSION.SDK_INT>=29&&"content".equals(uri.getScheme()))try{Uri mapped=MediaStore.getMediaUri(c,uri);if(mapped!=null)key=mapped;}catch(RuntimeException ignored){}if(!seen.add(key.toString().replace("/external_primary/","/external/")))continue;String name=uri.getLastPathSegment(),mime=null;long size=-1;try{mime=c.getContentResolver().getType(uri);}catch(RuntimeException ignored){}try(Cursor cursor=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){name=cursor.getString(0);if(!cursor.isNull(1))size=cursor.getLong(1);}}catch(RuntimeException ignored){}String title=item.mediaMetadata.title==null?"Áudio favorito":item.mediaMetadata.title.toString();String ext=extension(name,mime);if(mime==null||!mime.startsWith("audio/"))mime=MediaDownloadService.mime(ext);queue.put(new JSONObject().put("uri",uri.toString()).put("title",DownloadHistory.text(title,160)).put("format",ext).put("name",DownloadLinks.filename(title)+"."+ext).put("mime",mime).put("size",size));}if(queue.length()==0)throw new IOException("Nenhuma favorita local disponível para copiar.");byte[] bytes=queue.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>MAX_JSON)throw new IOException("A lista de favoritas excede o limite. Divida a seleção.");String name="onda-favorites-"+UUID.randomUUID()+".json";try(FileOutputStream out=new FileOutputStream(new File(c.getCacheDir(),name))){out.write(bytes);}return name;}
 static JSONArray read(Context c,String name)throws Exception{if(name==null||!name.matches("onda-favorites-[a-f0-9-]{36}\\.json"))throw new IOException("Pedido de cópia inválido");File f=new File(c.getCacheDir(),name);try{if(f.length()<2||f.length()>MAX_JSON)throw new IOException("Lista inválida");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>MAX_JSON)throw new IOException("Lista muito grande");out.write(b,0,n);}}JSONArray a=new JSONArray(out.toString("UTF-8"));if(a.length()==0||a.length()>MAX_ITEMS)throw new IOException("Lista inválida");return a;}finally{f.delete();}}
 static long copy(Context c,Uri source,Uri target,long expected,Control control)throws IOException{if(!Arrays.asList("content","file").contains(source.getScheme())||!"content".equals(target.getScheme())||source.equals(target))throw new IOException("Origem ou destino inválido");if(expected>MAX)throw new IOException("Arquivo excede 512 MB");long count=0;try(InputStream in=c.getContentResolver().openInputStream(source);OutputStream out=c.getContentResolver().openOutputStream(target,"wt")){if(in==null||out==null)throw new IOException("Arquivo indisponível");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){control.check();if(count+n>MAX)throw new IOException("Arquivo excede 512 MB");out.write(b,0,n);count+=n;control.bytes(count,expected);}control.check();if(count==0||expected>=0&&count!=expected)throw new IOException("A origem mudou ou a cópia ficou incompleta");return count;}}
}
